def process(clean_theft_data) -> pd.DataFrame:
    df = clean_theft_data
    growth = []
    for theft_type in df['theft_type'].unique():
        data_2020 = df[(df['theft_type'] == theft_type) & (df['year'] == 2020)]['reports'].values
        data_2024 = df[(df['theft_type'] == theft_type) & (df['year'] == 2024)]['reports'].values

        if len(data_2020) > 0 and len(data_2024) > 0:
            reports_2020 = data_2020[0]
            reports_2024 = data_2024[0]
            growth_rate = ((reports_2024 - reports_2020) / reports_2020) * 100
            growth.append({'theft_type': theft_type, '2020_reports': reports_2020, '2024_reports': reports_2024, 'growth_rate_pct': growth_rate})

    return pd.DataFrame(growth)
